import json
from pathlib import Path
value = json.loads(Path('world/pages/reviews-1.json').read_text())
subject = 'site:shopify-catalogue-example'
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
def records(node):
    if isinstance(node, dict):
        if node.get('subject') == subject and node.get('digest') == digest:
            yield {key: node.get(key) for key in ('subject', 'digest', 'verdict', 'seq', 'host_provider', 'host_turn')}
        for child in node.values():
            yield from records(child)
    elif isinstance(node, list):
        for child in node:
            yield from records(child)
print(json.dumps({'exact_digest_reviews_in_projection': list(records(value))}))
